#!/usr/bin/env bash
#
# The one-time setup of CI's cloud-tests check (README.md, "Cloud tests"). It walks the repository
# owner through creating the private test game and an Open Cloud API key, then stores the secret
# ROBLOX_API_KEY and the variables ROBLOX_TEST_UNIVERSE_ID and ROBLOX_TEST_PLACE_ID in GitHub with gh.
# Run it in your own terminal, so the key is never typed anywhere else:
#   bash scripts/ci/setup-cloud-tests.sh
#
# Generated by the /wizard skill (mattpocock-skills 1.3.1). Everything above the "STAGES" marker is its
# wizard library, with three changes: the helpers this wizard doesn't use are left out (banner, confirm,
# write_env); ${e} is braced in ask() for shellcheck (SC1087); and on Windows open_url uses PowerShell's
# Start-Process instead of explorer.exe, which reported failure for both pages and opened only the first
# (the API Keys URL, with its ?activeTab= query, never opened; 2026-10-24). The stages are below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1" quoted="${1//"'"/"''"}"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v powershell.exe >/dev/null 2>&1; then
      powershell.exe -NoProfile -NonInteractive -Command "Start-Process '$quoted'"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

# The repository's root, so gh stores the values in this repository.
cd "$(dirname "$0")/../.."

# GitHub CLI's Windows installer puts gh in this folder, which a Git Bash window may not have on its PATH.
if ! command -v gh >/dev/null 2>&1 && [[ -x "/c/Program Files/GitHub CLI/gh.exe" ]]; then
  PATH="$PATH:/c/Program Files/GitHub CLI"
fi

# ask_id KEY "Prompt" asks until the answer is a number (Roblox's IDs are).
ask_id() {
  while true; do
    ask "$1" "$2"
    [[ "${!1}" =~ ^[0-9]+$ ]] && return 0
    warn "That isn't a number: copy it again from the game's ⋯ menu."
  done
}

stage "Before you start"
say "CI's cloud-tests check runs the whole test suite inside Roblox. It needs, stored in GitHub:"
step "a private test game on your own account, 'Blox Champions Tests': its two ID numbers"
say "  (GitHub variables ROBLOX_TEST_UNIVERSE_ID and ROBLOX_TEST_PLACE_ID);"
step "an Open Cloud API key on your own account that can only upload to and run code in that game"
say "  (GitHub secret ROBLOX_API_KEY)."
note "Nothing is saved on this computer: the values go straight to GitHub, and the key is typed hidden."
note "So a re-run asks for every value again. Stop any time with Ctrl-C."
if ! command -v gh >/dev/null 2>&1; then
  warn "GitHub CLI (gh) is not installed: get it from https://cli.github.com, then run this again."
  exit 1
fi
if ! gh auth status >/dev/null 2>&1; then
  warn "GitHub CLI is not logged in: run 'gh auth login', then run this again."
  exit 1
fi
say ""
say "The values will be stored in ${BOLD}$(gh repo view --json nameWithOwner --jq .nameWithOwner)${RESET}."
pause "Press Enter to start."

stage "Create the test game"
say "The tests get their own private game, so they never touch the real one. What's in it doesn't"
say "matter: CI uploads the test place as a new version of it on every run."
step "In Roblox Studio, click File → New: a new place (a Baseplate) opens in a second window."
step "If Rojo asks there whether to connect, click Dismiss: Rojo is for your Blox Champions place."
step "Publish it from the File menu: its publish item opens the 'Publish Experience' window."
step "Name: Blox Champions Tests. Creator: leave 'Me', your own account."
step "Team Create: turn it off (nobody edits this game in Studio). Then click Create."
note "Data Sharing is your choice (the window says what it shares); CI uploads every test place, which"
note "holds the game's code and tests, as a version of this game. New games start private: keep it so."
note "Then close that Studio window; if it asks to save, don't: the game is already published."
pause "Press Enter once it is published."

stage "Copy the game's two IDs"
open_url "https://create.roblox.com/dashboard/creations"
step "The account switcher (upper-left) should show your own account, which owns the test game."
step "Hover over the 'Blox Champions Tests' tile, click its ⋯ button, and choose 'Copy Universe ID'."
ask_id ROBLOX_TEST_UNIVERSE_ID "Paste the Universe ID:"
step "Open the same ⋯ menu again and choose 'Copy Start Place ID'."
ask_id ROBLOX_TEST_PLACE_ID "Paste the Start Place ID:"
set_var ROBLOX_TEST_UNIVERSE_ID "$ROBLOX_TEST_UNIVERSE_ID"
set_var ROBLOX_TEST_PLACE_ID "$ROBLOX_TEST_PLACE_ID"
pause "Press Enter to continue."

stage "Create the API key"
open_url "https://create.roblox.com/dashboard/credentials?activeTab=ApiKeysTab"
step "Check the account switcher (upper-left) shows your own account: the key belongs to you."
step "Click 'Create API Key' and name it: blox-champions-ci"
step "Access Permissions → Select API System → universe-places. Turn on its 'Restrict by Experience'"
say "  (it starts off), pick Blox Champions Tests, and add the operation Write."
step "Select API System again → luau-execution-sessions: the same three things."
note "Restricted that way, the key reaches only the test game."
step "Security: leave 'Restrict IP addresses' off (GitHub's machines have no fixed address)."
note "If it insists on an address, enter 0.0.0.0/0, which means any address."
step "Leave the expiration date empty, click 'Save & Generate key', then 'Copy Key to Clipboard'."
warn "The key works like a password: paste it only into this window, never into a chat or a file."
pause "Press Enter once the key is copied."

stage "Store the key in GitHub"
while true; do
  ask_secret ROBLOX_API_KEY "Paste the API key (it stays hidden):"
  [[ -n "$ROBLOX_API_KEY" ]] && break
  warn "Nothing was pasted: try again."
done
set_secret ROBLOX_API_KEY "$ROBLOX_API_KEY"
unset ROBLOX_API_KEY
pause "Press Enter to finish."

finish
if [[ " ${SKIPPED[*]-} " != *"GitHub variable"* ]]; then
  note "set 2 GitHub variable(s): ROBLOX_TEST_UNIVERSE_ID ROBLOX_TEST_PLACE_ID"
fi
say ""
say "Next: CI's cloud-tests check runs on every pull request and every push to main. To re-run a"
say "failed check now, open the run on GitHub (the pull request's Checks tab), 'Re-run failed jobs'."
say ""
note "Roblox turns off a key that goes unused for 60 days (status Auto-Expired). CI uses it on every"
note "run, so that only happens after a long pause: then turn its 'Enable Key' toggle off and on at"
note "https://create.roblox.com/dashboard/credentials?activeTab=ApiKeysTab."
note "Lost the key? Keep no copy: open blox-champions-ci on that page, click 'Regenerate Key', and run"
note "this wizard again, re-using the test game you have: copy its IDs again, then paste the new key."
printf '\n'
}

run_wizard "$@"; exit
